def transform(grid):
    """Recolor the recurring marked phase of 2x2 tiles (color 2 -> 8)."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    anchors = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
